window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["opencode.ai"]={html:"<div class=\"own-opencode-ai\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"oc-nav\">\n    <a class=\"oc-brand\" href=\"#oc-top\" aria-label=\"Northwind home\">\n      <pre class=\"oc-wordmark oc-wordmark-sm\" aria-hidden=\"true\">█ █  ███  ██   ███  █ █  █   █  ███  █ █  ██ \n███  █ █  █ █   █   █ █  █   █   █   ███  █ █\n█ █  █ █  ██    █   ███  █ █ █   █   █ █  █ █\n█ █  █ █  █ █   █   █ █  ██ ██   █   █ █  █ █\n█ █  ███  █ █   █   █ █  █   █  ███  █ █  ██ </pre>\n      <span class=\"oc-sr\">Northwind</span>\n    </a>\n    <nav class=\"oc-nav-links\" aria-label=\"Primary\">\n      <a href=\"#oc-stats\">Regions <span class=\"oc-count\">[42]</span></a>\n      <a href=\"#oc-docs\">Docs</a>\n      <a href=\"#oc-faq\">FAQ</a>\n      <a href=\"#oc-quotes\">Customers</a>\n    </nav>\n    <div class=\"oc-nav-right\">\n      <button class=\"oc-iconbtn\" type=\"button\" aria-label=\"Search\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>\n      </button>\n      <a class=\"oc-btn oc-btn-primary\" href=\"#oc-top\">Download</a>\n      <button class=\"oc-burger\" type=\"button\" aria-label=\"Menu\" data-oc-burger>\n        <span aria-hidden=\"true\">[+]</span>\n      </button>\n    </div>\n    <nav class=\"oc-drawer\" aria-label=\"Mobile\" data-oc-drawer hidden>\n      <a href=\"#oc-stats\">Regions [42]</a>\n      <a href=\"#oc-docs\">Docs</a>\n      <a href=\"#oc-faq\">FAQ</a>\n      <a href=\"#oc-quotes\">Customers</a>\n    </nav>\n  </header>\n\n  <div class=\"oc-clip\">\n  <!-- ── HERO ─────────────────────────────────────────────────────────── -->\n  <section class=\"oc-hero\" id=\"oc-top\" aria-labelledby=\"ocHeroH\">\n    <p class=\"oc-badge-news\">News</p>\n    <h1 id=\"ocHeroH\">The open operations agent for your whole data stack</h1>\n    <p class=\"oc-hero-sub\">Ask a question in plain text. Northwind loads the right connectors, runs the query, and writes the answer back to your board — locally or in the region you choose.</p>\n\n    <div class=\"oc-install\">\n      <div class=\"oc-tabs\" role=\"tablist\" aria-label=\"Install method\">\n        <button class=\"oc-tab on\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-oc-tab=\"curl\">curl</button>\n        <button class=\"oc-tab\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-oc-tab=\"npm\">npm</button>\n        <button class=\"oc-tab\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-oc-tab=\"brew\">brew</button>\n      </div>\n      <div class=\"oc-snippet\" data-oc-snippet>\n        <code data-oc-cmd>curl -fsSL https://get.northwind.dev/install | bash</code>\n        <button class=\"oc-snippet-copy\" type=\"button\" aria-label=\"Copy command\" data-oc-copy>\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"9\" y=\"9\" width=\"11\" height=\"11\" rx=\"1\"/><path d=\"M5 15V5h10\"/></svg>\n        </button>\n      </div>\n    </div>\n\n    <div class=\"oc-hero-cta\">\n      <a class=\"oc-btn oc-btn-primary oc-btn-lg\" href=\"#oc-top\">Read the docs &rarr;</a>\n      <a class=\"oc-btn oc-btn-secondary oc-btn-lg\" href=\"#oc-stats\">See the numbers</a>\n    </div>\n  </section>\n\n  <!-- ── DARK TUI MOCKUP ──────────────────────────────────────────────── -->\n  <section class=\"oc-tui\" aria-label=\"Northwind terminal interface\">\n    <div class=\"oc-tui-inner\">\n      <pre class=\"oc-tui-mark\" aria-hidden=\"true\">\n ██   ██  ██████  ██████  ████████ ██   ██ ██     ██ ██ ███    ██ ██████\n ███  ██ ██    ██ ██   ██    ██    ██   ██ ██     ██ ██ ████   ██ ██   ██\n ██ █ ██ ██    ██ ██████     ██    ███████ ██  █  ██ ██ ██ ██  ██ ██   ██\n ██  ███ ██    ██ ██   ██    ██    ██   ██ ██ ███ ██ ██ ██  ██ ██ ██   ██\n ██   ██  ██████  ██   ██    ██    ██   ██  ███ ███  ██ ██   ████ ██████</pre>\n      <div class=\"oc-prompt\">\n        <span class=\"oc-pipe\" aria-hidden=\"true\">|</span>\n        <span class=\"oc-prompt-cmd\">Build</span>\n        <span class=\"oc-prompt-model\">[Northwind Local]</span>\n        <span class=\"oc-prompt-hint\">pulling ops.daily_throughput …</span>\n        <span class=\"oc-caret\" aria-hidden=\"true\"></span>\n      </div>\n      <div class=\"oc-tui-keys\" aria-hidden=\"true\">\n        <span><b>tab</b> switch region</span>\n        <span><b>ctrl-p</b> commands</span>\n        <span><b>ctrl-r</b> refresh board</span>\n        <span><b>?</b> help</span>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── STATS ─────────────────────────────────────────────────────────── -->\n  <section class=\"oc-stats\" id=\"oc-stats\" aria-labelledby=\"ocStatsH\">\n    <div class=\"oc-stats-head\">\n      <h2 id=\"ocStatsH\">Built for the data you already have</h2>\n      <p>Northwind reads warehouses, CSVs, and webhooks without copying them out. These charts refresh on the same sync schedule as your board.</p>\n    </div>\n    <div class=\"oc-charts\">\n      <figure class=\"oc-chart\">\n        <svg viewBox=\"0 0 260 90\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n          <polyline points=\"0,74 22,68 44,70 66,55 88,58 110,42 132,46 154,30 176,34 198,20 220,26 242,12 260,16\"/>\n          <g class=\"oc-dots\"><circle cx=\"66\" cy=\"55\" r=\"2\"/><circle cx=\"132\" cy=\"46\" r=\"2\"/><circle cx=\"198\" cy=\"20\" r=\"2\"/></g>\n        </svg>\n        <figcaption>Fig 1. Throughput up 12.4% QoQ</figcaption>\n      </figure>\n      <figure class=\"oc-chart\">\n        <svg viewBox=\"0 0 260 90\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n          <polyline points=\"0,60 22,62 44,52 66,56 88,44 110,48 132,36 154,40 176,28 198,32 220,22 242,24 260,14\"/>\n          <g class=\"oc-dots\"><circle cx=\"44\" cy=\"52\" r=\"2\"/><circle cx=\"110\" cy=\"48\" r=\"2\"/><circle cx=\"176\" cy=\"28\" r=\"2\"/></g>\n        </svg>\n        <figcaption>Fig 2. 42 regions connected</figcaption>\n      </figure>\n      <figure class=\"oc-chart\">\n        <svg viewBox=\"0 0 260 90\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n          <polyline points=\"0,80 22,70 44,74 66,58 88,62 110,50 132,54 154,38 176,42 198,30 220,18 242,22 260,10\"/>\n          <g class=\"oc-dots\"><circle cx=\"66\" cy=\"58\" r=\"2\"/><circle cx=\"132\" cy=\"54\" r=\"2\"/><circle cx=\"220\" cy=\"18\" r=\"2\"/></g>\n        </svg>\n        <figcaption>Fig 3. 6.5M events analyzed daily</figcaption>\n      </figure>\n    </div>\n  </section>\n\n  <!-- ── DOCS FEATURES ─────────────────────────────────────────────────── -->\n  <section class=\"oc-docs\" id=\"oc-docs\" aria-labelledby=\"ocDocsH\">\n    <div class=\"oc-docs-head\">\n      <h2 id=\"ocDocsH\">What is Northwind?</h2>\n      <hr class=\"oc-rule\">\n    </div>\n    <ul class=\"oc-rows\">\n      <li><b class=\"oc-mark\">[+]</b><span class=\"oc-row-label\">Warehouse connectors</span><span class=\"oc-row-desc\">Reads Postgres, BigQuery, and S3 without a copy step.</span></li>\n      <li><b class=\"oc-mark\">[+]</b><span class=\"oc-row-label\">Plain-text queries</span><span class=\"oc-row-desc\">Ask in English; the agent writes the SQL and shows its work.</span></li>\n      <li><b class=\"oc-mark\">[+]</b><span class=\"oc-row-label\">Local or cloud</span><span class=\"oc-row-desc\">Run inference on your machine or a region you control.</span></li>\n      <li><b class=\"oc-mark\">[+]</b><span class=\"oc-row-label\">Scheduled boards</span><span class=\"oc-row-desc\">Every answer can be pinned and refreshed on a cron.</span></li>\n      <li><b class=\"oc-mark\">[x]</b><span class=\"oc-row-label\">Audit trail</span><span class=\"oc-row-desc\">Every query, export, and credential use is logged.</span></li>\n    </ul>\n  </section>\n\n  <!-- ── TESTIMONIALS ──────────────────────────────────────────────────── -->\n  <section class=\"oc-quotes\" id=\"oc-quotes\" aria-labelledby=\"ocQuotesH\">\n    <div class=\"oc-docs-head\">\n      <h2 id=\"ocQuotesH\">Built for teams who ship</h2>\n      <hr class=\"oc-rule\">\n    </div>\n    <div class=\"oc-quote-list\">\n      <article class=\"oc-quote\">\n        <span class=\"oc-avatar\" aria-hidden=\"true\">DO</span>\n        <div>\n          <p class=\"oc-quote-who\">Dana Ocampo &middot; Operations Lead &middot; Northbeam</p>\n          <p class=\"oc-quote-text\">\"Our Monday board went from a two-hour scramble to a single question. Northwind wrote the query and I approved it.\"</p>\n        </div>\n      </article>\n      <article class=\"oc-quote\">\n        <span class=\"oc-avatar\" aria-hidden=\"true\">RS</span>\n        <div>\n          <p class=\"oc-quote-who\">Ravi Sandhu &middot; Head of Data &middot; Cobalt Freight</p>\n          <p class=\"oc-quote-text\">\"Running inference locally was the whole reason we could adopt it. Nothing sensitive leaves our network.\"</p>\n        </div>\n      </article>\n      <article class=\"oc-quote\">\n        <span class=\"oc-avatar\" aria-hidden=\"true\">LM</span>\n        <div>\n          <p class=\"oc-quote-who\">Lena Marchetti &middot; CFO &middot; Harbor Grid</p>\n          <p class=\"oc-quote-text\">\"I ask for the number, I get the number, and I can see exactly which tables it touched.\"</p>\n        </div>\n      </article>\n    </div>\n  </section>\n\n  <!-- ── FAQ ───────────────────────────────────────────────────────────── -->\n  <section class=\"oc-faq\" id=\"oc-faq\" aria-labelledby=\"ocFaqH\">\n    <div class=\"oc-docs-head\">\n      <h2 id=\"ocFaqH\">FAQ</h2>\n      <hr class=\"oc-rule\">\n    </div>\n    <div class=\"oc-faq-list\">\n      <div class=\"oc-faq-row\">\n        <h3><span class=\"oc-mark\" aria-hidden=\"true\">+</span> Does Northwind store my data?</h3>\n        <p>No. It reads your warehouse in place and keeps only the query and its result cache. The cloud tier is opt-in per region.</p>\n      </div>\n      <div class=\"oc-faq-row\">\n        <h3><span class=\"oc-mark\" aria-hidden=\"true\">&minus;</span> Which warehouses are supported?</h3>\n        <p>Postgres, MySQL, BigQuery, Snowflake, Redshift, S3, and any source you can expose as a CSV drop or webhook.</p>\n      </div>\n      <div class=\"oc-faq-row\">\n        <h3><span class=\"oc-mark\" aria-hidden=\"true\">+</span> Can I run it without internet?</h3>\n        <p>Yes. The installer bundles the local runtime; models download once and run offline after that.</p>\n      </div>\n      <div class=\"oc-faq-row\">\n        <h3><span class=\"oc-mark\" aria-hidden=\"true\">+</span> How is pricing measured?</h3>\n        <p>Per connected region, per month. The Free tier covers one region and five dashboards; Pro and Max scale from there.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── FOOTER ────────────────────────────────────────────────────────── -->\n  <footer class=\"oc-foot\">\n    <nav class=\"oc-foot-grid\" aria-label=\"Footer\">\n      <a href=\"#oc-top\">Install</a>\n      <a href=\"#oc-docs\">Docs</a>\n      <a href=\"#oc-stats\">Changelog</a>\n      <a href=\"#oc-quotes\">Customers</a>\n      <a href=\"#oc-faq\">Support</a>\n    </nav>\n    <div class=\"oc-foot-bottom\">\n      <span>&copy; 2026 Northwind</span>\n      <span class=\"oc-foot-utils\"><a href=\"#\">Brand</a> &middot; <a href=\"#\">Privacy</a> &middot; <a href=\"#\">Terms</a> &middot; English &#9662;</span>\n    </div>\n  </footer>\n  </div><!-- /.oc-clip -->\n</div>\n",css:"/* ══ OPENCODE.AI — own layout for showcase.html ═════════════════════════════\n   A terminal-native marketing page rendered entirely in a monospaced face on a\n   warm cream canvas: ASCII block-pixel wordmark, bracketed [+] / [-] markers as\n   bullets, 4px-radius interactive elements, 96px section rhythm, and one\n   full-bleed dark TUI mockup as the single visual moment. Ported from the\n   DESIGN.md token vocabulary. Container queries mirror the documented\n   breakpoints so the Tablet (820) and Phone (390) frames reflow. */\n\n.own-opencode-ai {\n  --primary: #201d1d;\n  --on-primary: #fdfcfc;\n  --ink: #201d1d;\n  --ink-deep: #0f0000;\n  --charcoal: #302c2c;\n  --body: #424245;\n  --mute: #646262;\n  --stone: #6e6e73;\n  --ash: #9a9898;\n  --canvas: #fdfcfc;\n  --surface-soft: #f8f7f7;\n  --surface-card: #f1eeee;\n  --surface-dark: #201d1d;\n  --surface-dark-elevated: #302c2c;\n  --hairline: rgba(15, 0, 0, 0.12);\n  --hairline-strong: #646262;\n  --on-dark: #fdfcfc;\n  --on-dark-mute: #9a9898;\n  --accent: #007aff;\n  --success: #30d158;\n\n  --mono: 'Berkeley Mono', 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace;\n\n  --r-sm: 4px;\n  --section: 96px;\n  --gut: clamp(20px, 5cqi, 40px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--mono);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n  border-radius: 13px;\n}\n.own-opencode-ai *, .own-opencode-ai *::before, .own-opencode-ai *::after { box-sizing: border-box; }\n.own-opencode-ai :focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; border-radius: var(--r-sm); }\n.own-opencode-ai .oc-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n.own-opencode-ai a { color: inherit; text-decoration: none; }\n.own-opencode-ai h1, .own-opencode-ai h2, .own-opencode-ai h3 { margin: 0; font-family: var(--mono); letter-spacing: 0; }\n.own-opencode-ai p { margin: 0; }\n.own-opencode-ai .oc-clip { overflow-x: clip; }\n.own-opencode-ai .oc-rule { border: 0; border-top: 1px solid var(--hairline); margin: 12px 0 0; }\n\n/* ── buttons ──────────────────────────────────────────────────────────── */\n.own-opencode-ai .oc-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 36px; padding: 0 20px; border-radius: var(--r-sm);\n  font-family: var(--mono); font-size: 16px; font-weight: 500; line-height: 2;\n  border: 1px solid transparent; white-space: nowrap;\n  transition: background-color .18s ease, color .18s ease, border-color .18s ease;\n}\n.own-opencode-ai .oc-btn-lg { height: 44px; }\n.own-opencode-ai .oc-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-opencode-ai .oc-btn-primary:hover { background: var(--ink-deep); }\n.own-opencode-ai .oc-btn-secondary { background: var(--canvas); color: var(--ink); border-color: var(--hairline-strong); }\n.own-opencode-ai .oc-btn-secondary:hover { border-color: var(--ink); }\n\n/* ── nav ───────────────────────────────────────────────────────────────── */\n.own-opencode-ai .oc-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 22px; flex-wrap: wrap;\n  height: 56px; margin: 0 var(--gut);\n  border-bottom: 1px solid var(--hairline);\n  background: rgba(253, 252, 252, .92);\n  backdrop-filter: blur(8px);\n}\n.own-opencode-ai .oc-brand { display: inline-flex; align-items: center; }\n.own-opencode-ai .oc-wordmark { margin: 0; font-size: 7px; line-height: 1.05; letter-spacing: 0; color: var(--ink); font-family: var(--mono); white-space: pre; }\n.own-opencode-ai .oc-nav-links { display: flex; align-items: center; gap: 22px; font-size: 16px; font-weight: 500; }\n.own-opencode-ai .oc-nav-links a:hover { text-decoration: underline; }\n.own-opencode-ai .oc-count { color: var(--mute); font-weight: 400; }\n.own-opencode-ai .oc-nav-right { display: flex; align-items: center; gap: 10px; margin-left: auto; }\n.own-opencode-ai .oc-iconbtn { display: grid; place-items: center; width: 36px; height: 36px; border: 0; background: none; cursor: pointer; }\n.own-opencode-ai .oc-iconbtn svg { width: 18px; height: 18px; fill: none; stroke: var(--ink); stroke-width: 2; }\n.own-opencode-ai .oc-burger { display: none; align-items: center; height: 36px; padding: 0 10px; border: 1px solid var(--hairline-strong); border-radius: var(--r-sm); background: var(--canvas); color: var(--ink); font-family: var(--mono); font-size: 14px; cursor: pointer; }\n.own-opencode-ai .oc-drawer { display: none; }\n\n/* ── hero ──────────────────────────────────────────────────────────────── */\n.own-opencode-ai .oc-hero { max-width: 960px; margin: 0 auto; padding: clamp(48px, 7cqi, 90px) var(--gut) 0; }\n.own-opencode-ai .oc-badge-news {\n  display: inline-block; padding: 2px 8px; border-radius: var(--r-sm);\n  background: var(--surface-dark); color: var(--on-dark); font-size: 14px; font-weight: 400; line-height: 1.6;\n  margin-bottom: 20px;\n}\n.own-opencode-ai .oc-hero h1 { font-size: clamp(28px, 4.2cqi, 38px); font-weight: 700; line-height: 1.5; max-width: 24ch; }\n.own-opencode-ai .oc-hero-sub { margin-top: 18px; max-width: 62ch; color: var(--body); font-size: 16px; line-height: 1.5; }\n.own-opencode-ai .oc-install { max-width: 640px; margin-top: 34px; }\n.own-opencode-ai .oc-tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--hairline); overflow-x: auto; scrollbar-width: none; }\n.own-opencode-ai .oc-tabs::-webkit-scrollbar { display: none; }\n.own-opencode-ai .oc-tab {\n  height: 40px; padding: 0 16px; border: 0; background: none; cursor: pointer;\n  font-family: var(--mono); font-size: 16px; font-weight: 500; color: var(--mute);\n  border-bottom: 2px solid transparent;\n}\n.own-opencode-ai .oc-tab.on { color: var(--ink); border-bottom-color: var(--ash); }\n.own-opencode-ai .oc-snippet {\n  display: flex; align-items: center; gap: 12px; margin-top: 14px;\n  padding: 12px 16px; border-radius: var(--r-sm); background: var(--surface-card);\n}\n.own-opencode-ai .oc-snippet code { flex: 1; min-width: 0; font-family: var(--mono); font-size: 16px; color: var(--ink); overflow-x: auto; white-space: nowrap; }\n.own-opencode-ai .oc-snippet-copy { display: grid; place-items: center; flex: none; width: 32px; height: 32px; border: 0; border-radius: var(--r-sm); background: var(--canvas); cursor: pointer; }\n.own-opencode-ai .oc-snippet-copy svg { width: 16px; height: 16px; fill: none; stroke: var(--ink); stroke-width: 1.8; }\n.own-opencode-ai .oc-snippet-copy:hover { box-shadow: inset 0 0 0 1px var(--hairline-strong); }\n.own-opencode-ai .oc-snippet-copy.done svg { stroke: var(--success); }\n.own-opencode-ai .oc-hero-cta { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }\n\n/* ── dark TUI ─────────────────────────────────────────────────────────── */\n.own-opencode-ai .oc-tui { margin-top: var(--section); padding: 64px 32px; background: var(--surface-dark); color: var(--on-dark); }\n.own-opencode-ai .oc-tui-inner { max-width: 960px; margin: 0 auto; }\n.own-opencode-ai .oc-tui-mark { margin: 0; font-family: var(--mono); font-size: clamp(4px, 1.4cqi, 13px); line-height: 1.1; color: var(--on-dark); white-space: pre; overflow: hidden; text-align: center; }\n.own-opencode-ai .oc-prompt {\n  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;\n  margin-top: 44px; padding: 8px 12px; border-radius: var(--r-sm);\n  background: var(--surface-dark-elevated); font-size: 16px;\n}\n.own-opencode-ai .oc-pipe { color: var(--ash); }\n.own-opencode-ai .oc-prompt-cmd { color: var(--on-dark); font-weight: 500; }\n.own-opencode-ai .oc-prompt-model { color: var(--accent); }\n.own-opencode-ai .oc-prompt-hint { color: var(--ash); }\n.own-opencode-ai .oc-caret { width: 9px; height: 18px; background: var(--on-dark); animation: oc-blink 1.1s steps(1) infinite; }\n@keyframes oc-blink { 50% { opacity: 0; } }\n.own-opencode-ai .oc-tui-keys { display: flex; flex-wrap: wrap; gap: 10px 28px; margin-top: 26px; color: var(--ash); font-size: 14px; }\n.own-opencode-ai .oc-tui-keys b { color: var(--on-dark); font-weight: 500; }\n\n/* ── stats / charts ───────────────────────────────────────────────────── */\n.own-opencode-ai .oc-stats { max-width: 1100px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-opencode-ai .oc-stats-head { max-width: 640px; }\n.own-opencode-ai .oc-stats-head h2 { font-size: 16px; font-weight: 700; }\n.own-opencode-ai .oc-stats-head p { margin-top: 12px; color: var(--body); font-size: 16px; }\n.own-opencode-ai .oc-charts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 34px; }\n.own-opencode-ai .oc-chart { margin: 0; padding: 16px; border: 1px solid var(--hairline); }\n.own-opencode-ai .oc-chart svg { display: block; width: 100%; height: 90px; }\n.own-opencode-ai .oc-chart polyline { fill: none; stroke: var(--body); stroke-width: 1.6; }\n.own-opencode-ai .oc-chart .oc-dots circle { fill: var(--body); }\n.own-opencode-ai .oc-chart figcaption { margin-top: 12px; font-size: 14px; color: var(--mute); }\n\n/* ── docs rows ────────────────────────────────────────────────────────── */\n.own-opencode-ai .oc-docs { max-width: 960px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-opencode-ai .oc-docs-head h2 { font-size: 16px; font-weight: 700; }\n.own-opencode-ai .oc-rows { list-style: none; margin: 22px 0 0; padding: 0; }\n.own-opencode-ai .oc-rows li { display: grid; grid-template-columns: auto 1fr; gap: 6px 14px; padding: 8px 0; color: var(--body); border-bottom: 1px solid var(--hairline); }\n.own-opencode-ai .oc-rows li:last-child { border-bottom: 0; }\n.own-opencode-ai .oc-mark { color: var(--ink); font-weight: 700; }\n.own-opencode-ai .oc-row-label { color: var(--ink); font-weight: 500; }\n.own-opencode-ai .oc-row-desc { grid-column: 2; }\n\n/* ── testimonials ─────────────────────────────────────────────────────── */\n.own-opencode-ai .oc-quotes { max-width: 960px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-opencode-ai .oc-quotes .oc-docs-head h2 { font-size: 16px; font-weight: 700; }\n.own-opencode-ai .oc-quote-list { display: grid; gap: 12px; margin-top: 22px; }\n.own-opencode-ai .oc-quote { display: flex; gap: 16px; padding: 16px 20px; border-radius: var(--r-sm); background: var(--surface-soft); color: var(--body); }\n.own-opencode-ai .oc-avatar { flex: none; width: 32px; height: 32px; border-radius: 9999px; display: grid; place-items: center; background: var(--surface-card); color: var(--ink); font-size: 12px; font-weight: 700; }\n.own-opencode-ai .oc-quote-who { color: var(--ink); font-weight: 500; }\n.own-opencode-ai .oc-quote-text { margin-top: 4px; }\n\n/* ── faq ───────────────────────────────────────────────────────────────── */\n.own-opencode-ai .oc-faq { max-width: 960px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-opencode-ai .oc-faq .oc-docs-head h2 { font-size: 16px; font-weight: 700; }\n.own-opencode-ai .oc-faq-list { margin-top: 22px; }\n.own-opencode-ai .oc-faq-row { padding: 12px 0; border-bottom: 1px solid var(--hairline); }\n.own-opencode-ai .oc-faq-row h3 { font-size: 16px; font-weight: 500; }\n.own-opencode-ai .oc-faq-row h3 .oc-mark { margin-right: 8px; }\n.own-opencode-ai .oc-faq-row p { margin-top: 8px; color: var(--body); }\n\n/* ── footer ────────────────────────────────────────────────────────────── */\n.own-opencode-ai .oc-foot { max-width: 960px; margin: 0 auto; padding: var(--section) var(--gut) 40px; }\n.own-opencode-ai .oc-foot-grid { display: grid; grid-template-columns: repeat(5, 1fr); border-top: 1px solid var(--hairline); border-bottom: 1px solid var(--hairline); }\n.own-opencode-ai .oc-foot-grid a { padding: 18px 8px; text-align: center; font-size: 14px; color: var(--body); border-left: 1px solid var(--hairline); }\n.own-opencode-ai .oc-foot-grid a:first-child { border-left: 0; }\n.own-opencode-ai .oc-foot-grid a:hover { color: var(--ink); text-decoration: underline; }\n.own-opencode-ai .oc-foot-bottom { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 10px 20px; margin-top: 18px; font-size: 14px; color: var(--mute); }\n.own-opencode-ai .oc-foot-utils a:hover { color: var(--ink); text-decoration: underline; }\n\n/* ── responsive (container queries mirror DESIGN.md breakpoints) ──────── */\n@container frame (max-width: 850px) {\n  .own-opencode-ai .oc-charts { grid-template-columns: 1fr 1fr; }\n  .own-opencode-ai .oc-foot-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-opencode-ai .oc-foot-grid a:nth-child(odd) { border-left: 0; }\n}\n@container frame (max-width: 768px) {\n  .own-opencode-ai .oc-nav-links { display: none; }\n  .own-opencode-ai .oc-burger { display: inline-flex; }\n  .own-opencode-ai .oc-drawer { display: grid; gap: 14px; width: 100%; order: 5; padding: 16px 0; border-top: 1px solid var(--hairline); background: var(--canvas); font-size: 16px; font-weight: 500; }\n  .own-opencode-ai .oc-drawer[hidden] { display: none; }\n  .own-opencode-ai { --section: 64px; }\n}\n@container frame (max-width: 640px) {\n  .own-opencode-ai .oc-hero h1 { font-size: 28px; }\n  .own-opencode-ai .oc-charts { grid-template-columns: 1fr; }\n  .own-opencode-ai .oc-tui { padding: 48px 20px; }\n  .own-opencode-ai .oc-foot-grid { grid-template-columns: 1fr; }\n  .own-opencode-ai .oc-foot-grid a { border-left: 0; border-top: 1px solid var(--hairline); }\n  .own-opencode-ai .oc-foot-grid a:first-child { border-top: 0; }\n}\n@container frame (max-width: 430px) {\n  .own-opencode-ai { --section: 48px; }\n  .own-opencode-ai .oc-hero-cta { flex-direction: column; align-items: stretch; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-opencode-ai *, .own-opencode-ai *::before, .own-opencode-ai *::after {\n    animation-duration: .001ms !important; animation-iteration-count: 1 !important;\n    transition-duration: .001ms !important;\n  }\n  .own-opencode-ai .oc-caret { animation: none; }\n}\n"};
/* ══ OPENCODE.AI — own layout behaviour for showcase.html ═══════════════════
   Registers window.OWN_LAYOUTS['opencode.ai'].init(root). Wires the mobile
   drawer, the install-method tab strip, and the snippet copy button. init
   returns a cleanup so unmounting removes every listener and timer. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var CMDS = {
    curl: 'curl -fsSL https://get.northwind.dev/install | bash',
    npm: 'npm install -g @northwind/cli',
    brew: 'brew install northwind'
  };

  OWN['opencode.ai'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var timers = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $sel(s) { return root.querySelector(s); }
      function $all(s) { return Array.prototype.slice.call(root.querySelectorAll(s)); }

      var burger = $sel('[data-oc-burger]');
      var drawer = $sel('[data-oc-drawer]');
      if (burger && drawer) {
        on(burger, 'click', function () {
          var open = drawer.hasAttribute('hidden');
          if (open) drawer.removeAttribute('hidden');
          else drawer.setAttribute('hidden', '');
          burger.setAttribute('aria-expanded', String(open));
        });
        on(drawer, 'click', function (e) {
          if (e.target.closest('a')) { drawer.setAttribute('hidden', ''); burger.setAttribute('aria-expanded', 'false'); }
        });
      }

      var cmdEl = $sel('[data-oc-cmd]');
      var tabs = $all('[data-oc-tab]');
      tabs.forEach(function (tab) {
        on(tab, 'click', function () {
          var key = tab.getAttribute('data-oc-tab');
          tabs.forEach(function (t) {
            var active = t === tab;
            t.classList.toggle('on', active);
            t.setAttribute('aria-selected', String(active));
          });
          if (cmdEl && CMDS[key]) cmdEl.textContent = CMDS[key];
        });
      });

      var copy = $sel('[data-oc-copy]');
      if (copy && cmdEl) {
        on(copy, 'click', function () {
          function done() {
            if (disposed) return;
            copy.classList.add('done');
            timers.push(window.setTimeout(function () {
              if (!disposed) copy.classList.remove('done');
            }, 1400));
          }
          var text = cmdEl.textContent || '';
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(done, done);
          } else {
            done();
          }
        });
      }

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        timers.forEach(function (id) { clearTimeout(id); });
      };
    }
  };
})();
